using System;using System.IO;using System.Linq;using System.Collections.Generic;using Frociart;
internal static class PostTestPropertyTests {
 sealed class Stop:Exception {}static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}static bool Choice(string id,int step,int seed){uint n=(uint)(seed*7937+step*65537);foreach(char c in id)n=unchecked(n*1664525+1013904223+c);n^=n>>16;n=unchecked(n*2246822519);n^=n>>13;return(n&1)==0;}
 static void Add(List<string> trace,FlowSource.Block block){if(trace.Count>=200)throw new Stop();trace.Add(block.Id);if(block.Kind==NodeKind.End)throw new Stop();}
 static bool Test(List<string> trace,FlowSource.Block block,int seed){Add(trace,block);return Choice(block.Id,trace.Count,seed);}
 static void Walk(IEnumerable<FlowSourcePlan.Statement> list,List<string> trace,int seed){foreach(var s in list){if(s.Kind==FlowSourcePlan.Kind.Instruction)Add(trace,s.Block);else if(s.Kind==FlowSourcePlan.Kind.If)Walk(Test(trace,s.Block,seed)?s.Body:s.Otherwise,trace,seed);else if(s.Kind==FlowSourcePlan.Kind.While){while(Test(trace,s.Block,seed)==s.LoopOnTrue)Walk(s.Body,trace,seed);}else{do{Walk(s.Body,trace,seed);}while(Test(trace,s.Block,seed)==s.LoopOnTrue);}}}
 static List<string> Planned(FlowSourcePlan p,int seed){var trace=new List<string>();try{Walk(p.Statements,trace,seed);}catch(Stop){}return trace;}
 static List<string> Direct(FlowSource.Scope s,int seed){var trace=new List<string>();string id=s.StartId;try{while(true){var b=s.Find(id);if(b.Kind==NodeKind.Decision)id=b.Next(Test(trace,b,seed)?"true":"false");else{Add(trace,b);id=b.Next("next");}}}catch(Stop){}return trace;}
 static Diagram Graph(int seed){var random=new Random(seed);var d=new Diagram();var nodes=new List<FlowNode>{new FlowNode{Id="start",Kind=NodeKind.Start,Text="Inizio"},new FlowNode{Id="init",Kind=NodeKind.Process,Text="x=0"}};int length=4+random.Next(24);for(int i=0;i<length;i++)nodes.Add(new FlowNode{Id="node"+i,Kind=random.Next(4)==0?NodeKind.Process:NodeKind.Decision,Text="x=x"});nodes.Add(new FlowNode{Id="end",Kind=NodeKind.End,Text="Fine"});for(int i=0;i<nodes.Count-1;i++){var b=nodes[i];d.Edges.Add(new FlowEdge{From=b.Id,To=nodes[i+1].Id,Branch=b.Kind==NodeKind.Decision?"true":"next"});if(b.Kind==NodeKind.Decision){b.Text="x>=0";d.Edges.Add(new FlowEdge{From=b.Id,To=nodes[1+random.Next(nodes.Count-1)].Id,Branch="false"});}}d.Nodes=nodes;return d;}
 static string Grammar(Random r,int depth){if(depth==0)return "x=x+1\n";switch(r.Next(4)){case 0:return "SE x>"+r.Next(5)+" ALLORA\n"+Grammar(r,depth-1)+"ALTRIMENTI\n"+Grammar(r,depth-1)+"FINE SE\n";case 1:return "MENTRE x<"+r.Next(6)+" FAI\n"+Grammar(r,depth-1)+"FINE MENTRE\n";case 2:return "RIPETI\n"+Grammar(r,depth-1)+"FINCHE x>="+r.Next(1,6)+"\n";default:return Grammar(r,depth-1)+Grammar(r,depth-1);}}
 static int Main(string[] args){try{int structured=0,explicitGraphs=0,traces=0;for(int i=0;i<600;i++){var p=FlowSource.Compile(Graph(97+i));Check(p.CanGenerate,"Synthetic graph compiles "+i);var scope=p.Scopes[0];var plan=FlowSourcePlan.Create(scope);if(!plan.Structured){explicitGraphs++;continue;}structured++;for(int seed=0;seed<24;seed++){var actual=Planned(plan,seed);var expected=Direct(scope,seed);Check(actual.SequenceEqual(expected),"Control-flow trace differs graph="+i+" seed="+seed+" direct="+String.Join(",",expected)+" planned="+String.Join(",",actual));traces++;}}for(int i=0;i<300;i++){string text="x=0\n"+Grammar(new Random(5000+i),3)+"STAMPA x";var p=FlowSource.Compile(FlowPseudocode.Decode(text));Check(p.CanGenerate,"Structured grammar compiles "+i);var scope=p.Scopes[0];var plan=FlowSourcePlan.Create(scope);if(!plan.Structured){File.WriteAllText(Path.Combine(args[0],"property-failed-grammar.txt"),text);throw new Exception("Structured grammar unexpectedly needs explicit edges: "+i);}for(int seed=0;seed<24;seed++){Check(Planned(plan,seed).SequenceEqual(Direct(scope,seed)),"Structured grammar trace differs "+i+" seed="+seed);traces++;}}
File.WriteAllText(Path.Combine(args[0],"property-counts.txt"),"graphs=900 structuredGrammar=300 structuredRandom="+structured+" explicit="+explicitGraphs+" traces="+traces);Console.WriteLine("POST_TEST_PROPERTY PASS checks="+checks+" structured="+structured+" fallback="+explicitGraphs+" traces="+traces);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
